using System.Text.Json.Nodes;

using Papuma.Kernel.Changes;

namespace Papuma.Kernel.Core.Tests.Spec;

/// <summary>
/// Runs <c>docs/spec/vectors/canonical.json</c> and <c>hash.json</c> — generated by the
/// independent Python reference in <c>docs/spec/reference</c> — against the kernel's
/// canonical JSON and v2 hash (ADR-025).
/// </summary>
public sealed class CanonicalAndHashVectorTests
{
    public static TheoryData<string> CanonicalCases() => Names("canonical.json", "cases");

    public static TheoryData<string> HashCases() => Names("hash.json", "hashes");

    public static TheoryData<int> KeyCases()
    {
        var data = new TheoryData<int>();
        for (var i = 0; i < ((JsonArray)Load("hash.json")["keys"]!).Count; i++)
        {
            data.Add(i);
        }

        return data;
    }

    [Theory]
    [MemberData(nameof(CanonicalCases))]
    public void Canonical_MatchesVector(string name)
    {
        var vector = Find("canonical.json", "cases", name);
        var node = JsonNode.Parse((string)vector["inputJson"]!);

        if (vector["error"] is JsonNode error)
        {
            var ex = Assert.Throws<CanonicalJsonException>(() => CanonicalJson.Serialize(node));
            Assert.Equal((string?)error, ex.Code);
            return;
        }

        Assert.Equal((string?)vector["canonical"], CanonicalJson.Serialize(node));
    }

    [Theory]
    [MemberData(nameof(KeyCases))]
    public void TenantKey_MatchesVector(int index)
    {
        var document = Load("hash.json");
        var vector = (JsonObject)((JsonArray)document["keys"]!)[index]!;

        var key = HashV2.DeriveTenantKey(MasterKey(document), (string)vector["tenantId"]!, (string)vector["typeName"]!);

        Assert.Equal((string?)vector["tenantKeyHex"], Convert.ToHexStringLower(key));
    }

    [Theory]
    [MemberData(nameof(HashCases))]
    public void Hash_MatchesVector(string name)
    {
        var document = Load("hash.json");
        var vector = Find("hash.json", "hashes", name);
        var value = JsonNode.Parse((string)vector["valueJson"]!);
        var key = HashV2.DeriveTenantKey(MasterKey(document), (string)vector["tenantId"]!, (string)vector["typeName"]!);

        Assert.Equal((string?)vector["canonical"], CanonicalJson.Serialize(value));
        Assert.Equal((string?)vector["hash"], HashV2.Hash(key, (string)document["kid"]!, value));
    }

    [Fact]
    public void KeyCheck_MatchesVector()
    {
        var document = Load("hash.json");

        Assert.Equal(
            (string?)document["keyCheck"]!["checkValue"],
            HashV2.KeyCheck(MasterKey(document)));
    }

    [Fact]
    public void Hash_IsEqualForEqualValues_AndDifferentAcrossTenantsAndTypes()
    {
        var document = Load("hash.json");
        string HashOf(string name) => (string)Find("hash.json", "hashes", name)["hash"]!;

        Assert.Equal(HashOf("number-by-value-integer-form"), HashOf("number-by-value-decimal-form"));
        Assert.Equal(HashOf("number-by-value-integer-form"), HashOf("number-by-value-exponent-form"));
        Assert.Equal(HashOf("object-key-order-is-irrelevant-a"), HashOf("object-key-order-is-irrelevant-b"));
        Assert.NotEqual(HashOf("string"), HashOf("another-tenant"));
        Assert.NotEqual(HashOf("string"), HashOf("another-type"));
        Assert.NotEqual(HashOf("string"), HashOf("platform-scope"));
        Assert.StartsWith($"v2:{(string)document["kid"]!}:", HashOf("string"), StringComparison.Ordinal);
    }

    private static byte[] MasterKey(JsonObject document) => Convert.FromHexString((string)document["masterKeyHex"]!);

    private static TheoryData<string> Names(string file, string array)
    {
        var data = new TheoryData<string>();
        foreach (var vector in (JsonArray)Load(file)[array]!)
        {
            data.Add((string)vector!["name"]!);
        }

        return data;
    }

    private static JsonObject Find(string file, string array, string name) =>
        ((JsonArray)Load(file)[array]!).Cast<JsonObject>().Single(v => (string?)v["name"] == name);

    [Fact]
    public void TheVectorsMasterKey_IsThePublishedTestKey_ThatConfigurationRefuses()
    {
        // The key FromBase64 refuses (review P-16) is the one the vectors and TestHashKeys publish.
        Assert.True(MasterKeyHashKeyProvider.IsPublishedTestKey(Convert.FromHexString((string)Load("hash.json")["masterKeyHex"]!)));
        Assert.False(MasterKeyHashKeyProvider.IsPublishedTestKey(new byte[32]));
        Assert.False(MasterKeyHashKeyProvider.IsPublishedTestKey(Convert.FromHexString(
            "000102030405060708090a0b0c0d0e0f101112131415161718191a1b1c1d1e1f20")));
    }

    private static JsonObject Load(string file) =>
        (JsonObject)JsonNode.Parse(File.ReadAllText(Path.Combine(RepoRoot(), "docs", "spec", "vectors", file)))!;

    private static string RepoRoot()
    {
        for (var directory = new DirectoryInfo(AppContext.BaseDirectory); directory is not null; directory = directory.Parent)
        {
            if (File.Exists(Path.Combine(directory.FullName, "Papuma.Kernel.slnx")))
            {
                return directory.FullName;
            }
        }

        throw new InvalidOperationException("Repository root (Papuma.Kernel.slnx) not found above the test output.");
    }
}
